pub fn schema_or_config<'py, T>(
    schema: &Bound<'py, PyDict>,
    config: Option<&Bound<'py, PyDict>>,
    schema_key: &Bound<'py, PyString>,
    config_key: &Bound<'py, PyString>,
) -> PyResult<Option<T>>
where
    T: FromPyObjectOwned<'py>,
{
    match schema.get_as(schema_key)? {
        Some(v) => Ok(Some(v)),
        None => match config {
            Some(config) => config.get_as(config_key),
            None => Ok(None),
        },
    }
}

pub fn schema_or_config_same<'py, T>(
    schema: &Bound<'py, PyDict>,
    config: Option<&Bound<'py, PyDict>>,
    key: &Bound<'py, PyString>,
) -> PyResult<Option<T>>
where
    T: FromPyObjectOwned<'py>,
{
    schema_or_config(schema, config, key, key)
}

pub fn is_strict(schema: &Bound<'_, PyDict>, config: Option<&Bound<'_, PyDict>>) -> PyResult<bool> {
    let py = schema.py();
    Ok(schema_or_config_same(schema, config, intern!(py, "strict"))?.unwrap_or(false))
}

enum SchemaErrorEnum {
    Message(String),
    ValidationError(ValidationError),
}

// we could perhaps do clever things here to store each schema error, or have different types for the top
// level error group, and other errors, we could perhaps also support error groups!?
#[pyclass(extends=PyException, module="pydantic_core._pydantic_core")]
pub struct SchemaError(SchemaErrorEnum);

impl fmt::Debug for SchemaError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "SchemaError({:?})", self.message())
    }
}

impl fmt::Display for SchemaError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.message())
    }
}

impl Error for SchemaError {
    #[cfg_attr(has_coverage_attribute, coverage(off))]
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        None
    }
}

impl SchemaError {
    pub fn new_err<A>(args: A) -> PyErr
    where
        A: PyErrArguments + Send + Sync + 'static,
    {
        PyErr::new::<SchemaError, A>(args)
    }

    pub fn from_val_error(py: Python, error: ValError) -> PyErr {
        match error {
            ValError::LineErrors(raw_errors) => {
                let line_errors = match raw_errors
                    .into_iter()
                    .map(|e| PyLineError::from_val_line_error(py, e))
                    .collect::<PyResult<_>>()
                {
                    Ok(errors) => errors,
                    Err(err) => return err,
                };
                let validation_error = ValidationError::new(
                    line_errors,
                    PyString::new(py, "Schema").into(),
                    InputType::Python,
                    false,
                );
                let schema_error = SchemaError(SchemaErrorEnum::ValidationError(validation_error));
                match Py::new(py, schema_error) {
                    Ok(err) => PyErr::from_value(err.into_bound(py).into_any()),
                    Err(err) => err,
                }
            }
            ValError::InternalErr(err) => err,
            ValError::Omit => Self::new_err("Unexpected Omit error."),
            ValError::UseDefault => Self::new_err("Unexpected UseDefault error."),
        }
    }

    fn message(&self) -> &str {
        match &self.0 {
            SchemaErrorEnum::Message(message) => message.as_str(),
            SchemaErrorEnum::ValidationError(_) => "<ValidationError>",
        }
    }
}

#[pymethods]
impl SchemaError {
    #[new]
    fn py_new(message: String) -> Self {
        Self(SchemaErrorEnum::Message(message))
    }

    fn error_count(&self) -> usize {
        match &self.0 {
            SchemaErrorEnum::Message(_) => 0,
            SchemaErrorEnum::ValidationError(error) => error.error_count(),
        }
    }

    fn errors(&self, py: Python) -> PyResult<Py<PyList>> {
        match &self.0 {
            SchemaErrorEnum::Message(_) => Ok(PyList::empty(py).unbind()),
            SchemaErrorEnum::ValidationError(error) => error.errors(py, false, false, true),
        }
    }

    fn __str__(&self, py: Python) -> String {
        match &self.0 {
            SchemaErrorEnum::Message(message) => message.clone(),
            SchemaErrorEnum::ValidationError(error) => error.display(py, Some("Invalid Schema:"), false),
        }
    }

    fn __repr__(&self, py: Python) -> String {
        match &self.0 {
            SchemaErrorEnum::Message(message) => format!("SchemaError({message:?})"),
            SchemaErrorEnum::ValidationError(error) => error.display(py, Some("Invalid Schema:"), false),
        }
    }
}

macro_rules! py_schema_error_type {
    ($( $msg_args:expr ),+ ) => {
        crate::tools::py_error_type!(crate::build_tools::SchemaError; $( $msg_args ),+)
    };
}
pub(crate) use py_schema_error_type;

macro_rules! py_schema_err {
    ($( $msg_args:expr ),+ ) => {
        Err(crate::build_tools::py_schema_error_type!($( $msg_args ),+))
    };
}
pub(crate) use py_schema_err;

#[derive(Debug, Clone, Copy, Eq, PartialEq)]
pub enum ExtraBehavior {
    Allow,
    Forbid,
    Ignore,
}

impl ExtraBehavior {
    pub fn from_schema_or_config(
        py: Python,
        schema: &Bound<'_, PyDict>,
        config: Option<&Bound<'_, PyDict>>,
        default: Self,
    ) -> PyResult<Self> {
        let extra_behavior = schema_or_config::<Option<Bound<'_, PyString>>>(
            schema,
            config,
            intern!(py, "extra_behavior"),
            intern!(py, "extra_fields_behavior"),
        )?
        .flatten();
        let res = match extra_behavior.as_ref().map(|s| s.to_str()).transpose()? {
            Some(s) => Self::from_str(s)?,
            None => default,
        };
        Ok(res)
    }
}

impl FromStr for ExtraBehavior {
    type Err = PyErr;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "allow" => Ok(Self::Allow),
            "forbid" => Ok(Self::Forbid),
            "ignore" => Ok(Self::Ignore),
            s => py_schema_err!("Invalid extra_behavior: `{s}`"),
        }
    }
}

/// A lazily-initialized value.
///
/// This is a basic replacement for `LazyLock` which is available only in Rust 1.80+.
pub struct LazyLock<T> {
    init: fn() -> T,
    value: OnceLock<T>,
}

impl<T> Deref for LazyLock<T> {
    type Target = T;

    fn deref(&self) -> &Self::Target {
        self.value.get_or_init(self.init)
    }
}

impl<T> LazyLock<T> {
    pub const fn new(init: fn() -> T) -> Self {
        Self {
            init,
            value: OnceLock::new(),
        }
    }
}

use pyo3::intern;
use pyo3::prelude::*;
use pyo3::sync::PyOnceLock;

static MISSING_SENTINEL_OBJECT: PyOnceLock<Py<PyAny>> = PyOnceLock::new();

pub fn get_missing_sentinel_object(py: Python<'_>) -> &Bound<'_, PyAny> {
    MISSING_SENTINEL_OBJECT
        .get_or_init(py, || {
            py.import(intern!(py, "pydantic_core"))
                .and_then(|core_module| core_module.getattr(intern!(py, "MISSING")))
                .unwrap()
                .into()
        })
        .bind(py)
}

use pyo3::intern;
use pyo3::prelude::*;
use pyo3::types::{PyAny, PyDict, PyType};

use crate::tools::SchemaDict;

pub fn get_prebuilt<T>(
    type_: &str,
    schema: &Bound<'_, PyDict>,
    prebuilt_attr_name: &str,
    extractor: impl FnOnce(Bound<'_, PyAny>) -> PyResult<Option<T>>,
) -> PyResult<Option<T>> {
    let py = schema.py();

    // we can only use prebuilt validators/serializers from models and Pydantic dataclasses.
    // However, we don't want to use a prebuilt structure from dataclasses if we have a `generic_origin`
    // as this means the dataclass was parametrized (so a generic alias instance), and `cls` in the
    // core schema is still the (unparametrized) class, meaning we would fetch the wrong validator/serializer.
    if !matches!(type_, "model" | "dataclass")
        || (type_ == "dataclass" && schema.contains(intern!(py, "generic_origin"))?)
    {
        return Ok(None);
    }

    let class: Bound<'_, PyType> = schema.get_as_req(intern!(py, "cls"))?;

    // Note: we NEED to use the __dict__ here (and perform get_item calls rather than getattr)
    // because we don't want to fetch prebuilt validators from parent classes.
    // We don't downcast here because __dict__ on a class is a readonly mappingproxy,
    // so we can just leave it as is and do get_item checks.
    let class_dict = class.getattr(intern!(py, "__dict__"))?;

    let is_complete: bool = class_dict
        .get_item(intern!(py, "__pydantic_complete__"))
        .is_ok_and(|b| b.extract().unwrap_or(false));

    if !is_complete {
        return Ok(None);
    }

    // Retrieve the prebuilt validator / serializer if available
    let prebuilt: Bound<'_, PyAny> = class_dict.get_item(prebuilt_attr_name)?;
    extractor(prebuilt)
}

use pyo3::prelude::*;
use pyo3::{PyTraverseError, PyVisit};
